-- Add every bullet fact from the supplied youth-focused Lily collection.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (829, $$Книга — это легальный телепорт: Ты можешь за секунду оказаться на Марсе, в средневековом замке или внутри компьютерной игры.$$),
  (830, $$Включается 3D-режиссер: В кино тебе показывают чужую картинку. В книге твой мозг сам создает спецэффекты, внешность героев и масштаб взрывов. Ты — главный режиссер.$$),
  (831, $$Прокачка «детективного зрения»: Читая книги, ты начинаешь видеть скрытые подсказки, быстрее разгадываешь тайны и понимаешь, кто злодей, еще в середине истории.$$),
  (832, $$Твой личный щит от манипуляций: Книги учат замечать обман и хитрость. Тебя будет невозможно развести на слабо или запутать глупыми слухами.$$),
  (833, $$Словарный запас как у секретного агента: Ты начнешь подбирать такие точные и крутые слова, что взрослые заслушаются, а споры со сверстниками ты будешь выигрывать одной фразой.$$),
  (834, $$Супер-фокус: Книги лечат «золотую рыбку» внутри нас. Тот, кто может читать книгу полчаса без телефона, легко сдаст любой экзамен и выучит что угодно.$$),
  (835, $$Юмор уровня «Шерлок»: Хорошие книги развивают топовое чувство юмора. Твои шутки станут тонкими, острыми и реально смешными.$$),
  (836, $$Свой внутренний мир: Книги делают тебя сложным и интересным человеком, с которым никогда не скучно поболтать на любую тему.$$),
  (837, $$Умение красиво писать: Школьные сочинения, посты в блог или сообщения в чатах будут получаться сами собой — без мучений и глупых ошибок.$$),
  (838, $$Генератор идей: Чтение соединяет в голове самые разные мысли. Ты сможешь придумывать оригинальные мемы, проекты или сценарии для видео, до которых другие просто не додумаются.$$),
  (839, $$Антистресс за 6 минут: Если ты злишься, устал или поссорился с кем-то, просто почитай книгу 6 минут. Твое сердце успокоится, а нервы расслабятся.$$),
  (840, $$Убежище от проблем: Книга — это место, где можно спрятаться от плохой погоды, школьных неурядиц или плохого настроения.$$),
  (841, $$Никаких кошмаров: Чтение бумажной книги на ночь расслабляет мозг, прогоняет страхи и дарит самые яркие и добрые сны.$$),
  (842, $$Легкое засыпание: Забудь про бессонницу. Книга плавно переключает твое тело в режим отдыха — без эффекта «залипания», как в телефоне.$$),
  (843, $$Бодрое утро: Если вечером читать бумагу, а не скроллить экран, утром ты проснешься со свежей головой и без чувства «разбитости».$$),
  (844, $$Психологический тренажер: В книгах герои проходят через кучу трудностей. Читая их истории, ты подсознательно учишься не сдаваться, когда тяжело тебе самому.$$),
  (845, $$Свобода от лайков: Книга не требует от тебя быть идеальным. Ей всё равно, сколько у тебя подписчиков, она просто дарит тебе крутую историю.$$),
  (846, $$Выход из «информационного шума»: Чтение помогает голове отдохнуть от бесконечных уведомлений, сообщений и тиктоков.$$),
  (847, $$Настоящий отдых для глаз: Глаза отдыхают, когда смотрят на обычную бумагу, а не на мерцающий пикселями экран смартфона.$$),
  (848, $$Чистый кайф: Найти «свою» книгу — это как найти идеальную видеоигру, от которой невозможно оторваться, пока не дойдешь до финала.$$),
  (849, $$Ты можешь прочитать чужие мысли: Книга позволяет заглянуть прямо в голову другому человеку и узнать, что он чувствует, когда ему страшно, весело или обидно.$$),
  (850, $$Развитие эмпатии: Читающие люди лучше понимают намеки, реже ссорятся с друзьями и умеют вовремя поддержать близких.$$),
  (851, $$Ты видишь людей насквозь: Литература дает такую базу характеров, что в реальной жизни ты начнешь сразу понимать, кто тебе врёт, кто трусит, а кто реально верный друг.$$),
  (852, $$Кодекс крутых напарников: Истории о дружбе (как в «Илиаде» или «Гарри Поттере») показывают, что такое настоящая преданность и как работает крутая команда.$$),
  (853, $$Свобода от стереотипов: Книги доказывают, что все люди разные, и судить кого-то по внешности или одежде — это глупо.$$),
  (854, $$Ты станешь магнитом для общения: Начитанные люди рассказывают истории так сочно и интересно, что вокруг них всегда собираются компании.$$),
  (855, $$Понимание родителей: Книги часто показывают ситуации со стороны взрослых. Ты начнешь понимать, почему родители иногда ворчат или переживают за тебя.$$),
  (856, $$Харизма на максимум: Чтение делает твой голос, мимику и уверенность в себе сильнее. Ты сможешь четко отстаивать свои границы.$$),
  (857, $$Интересные темы для свиданий: Обсудить классный сюжет или необычного героя — это в сто раз круче, чем уныло молчать или пересылать банальные тиктоки.$$),
  (858, $$Ты никогда не будешь одинок: Книга — это друг, который всегда с тобой. В поезде, в очереди или дома в плохой день она с удовольствием развлечет тебя.$$),
  (859, $$«Голодные игры» придумали греки: Сюжет книги о выживании подростков полностью списан с древнего мифа о Тесее и чудовище Минотавре.$$),
  (860, $$«Матрица» — это идея Платона: Мысль о том, что наш мир — лишь иллюзия, а люди видят только тени реальности, философ Платон описал еще 2400 лет назад.$$),
  (861, $$Заклинания Роулинг — это реальный язык: Все заклинания в «Гарри Поттере» (Люмос, Экспеллиармус) — это латынь, взятая из древних книг по медицине и магии.$$),
  (862, $$Сюжет «Короля Льва» взят из классики: История Симбы, который мстит дяде за отца, — это точный пересказ древних греческих трагедий о мести.$$),
  (863, $$Оборотни появились в древней литературе: Первое детальное описание превращения человека в волка было написано в римском романе «Сатирикон» две тысячи лет назад.$$),
  (864, $$Кольцо Всевластья придумал Платон: Идея кольца, которое делает тебя невидимым, но портит твой характер (база для Толкина), впервые появилась в книге Платона «Государство».$$),
  (865, $$Космические миссии зовут в честь богов: Программа «Аполлон» названа в честь греческого бога света и искусств, потому что его описывали как того, кто может достичь любых высот.$$),
  (866, $$Супергерои списаны с Геракла: Все фишки Супермена, Тора или Халка (сверхсила, уязвимость, спасение мира) придуманы в античных рассказах про Геракла.$$),
  (867, $$Суперзлодеев учат по хроникам: Образы безумных тиранов с тяжелым прошлым (вроде Таноса) сценаристы Marvel строят по книгам римского историка Тацита.$$),
  (868, $$Клиффхэнгеры придумали поэты: Обрывать серию сериала на самом интересном месте придумали авторы древних свитков, чтобы читатели быстрее бежали покупать продолжение.$$),
  (869, $$Календарь от Юлия Цезаря: Мы живем по календарю, который придумал римский правитель Юлий Цезарь. Идея прибавлять один день раз в 4 года (високосный год) — его фишка.$$),
  (870, $$Названия месяцев — это имена богов: Март назван в честь Марса, июль — в честь Юлия Цезаря, август — в честь Октавиана Августа.$$),
  (871, $$Дни недели на английском: В иностранных языках дни недели названы в честь планет и богов из книг. Saturday — день Сатурна, Sunday — день Солнца.$$),
  (872, $$Знаки зодиака из древних свитков: Система 12 созвездий, по которой люди до сих пор смотрят гороскопы, была записана в античном справочнике «Тетрабиблос».$$),
  (873, $$Откуда пошли «Милли»: Римляне ставили вдоль дорог столбы через каждые 1000 двойных шагов (Milia passuum). Так появилось слово «миля».$$),
  (874, $$Деньги из храма: Слово «монета» появилось потому, что первый монетный двор Рима находился при храме богини Юноны Монеты (Советницы).$$),
  (875, $$Первый фастфуд: Придорожные кафе, где в прилавки были встроены чаны с горячей едой навынос, были мегапопулярны в Риме две тысячи лет назад. Они назывались термополии.$$),
  (876, $$Многоэтажки придумали римляне: Большие жилые дома в несколько этажей, где внизу были магазины, а вверху квартиры, назывались инсулы.$$),
  (877, $$Первые торговые центры: В Риме существовал рынок Траяна — огромный комплекс из 150 лавок под одной крышей с крытыми галереями.$$),
  (878, $$Стекло в окнах: Первыми делать плоские прозрачные стекла для окон научились римские мастера в I веке н.э., сделав дома светлыми и уютными.$$),
  (879, $$Деление на главы: В Александрийской библиотеке филологи делили «Илиаду» ровно на 24 части — по количеству букв в алфавите, чтобы свитки было удобно носить.$$),
  (880, $$Как появилось слово «Плагиат»: Римский поэт Марциал обозвал «плагиатором» вора, который украл его стихи, сравнив это с похищением детей в рабство (plagium).$$),
  (881, $$Басни про животных: Все истории про Лису и Виноград или Волка и Ягненка придумал греческий раб Эзоп. Мы до сих пор пересказываем его шутки.$$),
  (882, $$Тайные чернила Овидия: Римский поэт Овидий советовал девушкам писать секретные записки свежим молоком. Когда оно высыхает, букв не видно, но если посыпать лист углем, текст проявится.$$),
  (883, $$Книги с секретом: Раньше мастера умели рисовать картины на срезе страниц. Когда книга закрыта — обрез кажется золотым. Но если сдвинуть страницы веером, проявляется тайный пейзаж.$$),
  (884, $$Слово «Робот» придумал писатель: Это слово впервые появилось не в лаборатории ученых, а в фантастической пьесе чешского писателя Карела Чапека в 1920 году.$$),
  (885, $$Пророчество о Титанике: Писатель Морган Робертсон написал книгу о гибели гигантского корабля «Титан» от столкновения с айсбергом за 14 лет до того, как реальный «Титаник» вышел в море.$$),
  (886, $$Наушники-ракушки Брэдбери: В 1953 году Рэй Брэдбери в книге «451 градус по Фаренгейту» описал крошечные радио-ракушки, которые вставляются в уши. Это точное описание наших AirPods.$$),
  (887, $$Атомная бомба из романа: Писатель Герберт Уэллс придумал и детально описал атомную бомбу в своем романе еще в 1914 году — задолго до того, как физики её создали.$$),
  (888, $$Язык Эльфов был первым: Толкин сначала полностью придумал эльфийские языки (квенья и синдарин), а мир Средиземья и сюжет «Властелина колец» сочинил потом — просто чтобы его языкам было где существовать.$$),
  (889, $$Прокачка мозга на МРТ: Ученые доказали, что чтение книг физически увеличивает количество связей в левой височной коре мозга. Мозг становится мощнее.$$),
  (890, $$Эффект спортивной тренировки: Когда ты читаешь, как герой бежит или дерется, твой мозг активирует те же зоны, как если бы ты делал это сам на стадионе.$$),
  (891, $$Глаза в тонусе: Мягкое чтение бумажной страницы тренирует фокус глаза, в отличие от залипания в экран, которое вызывает спазм мышц.$$),
  (892, $$Защита от сухости глаз: Когда ты смотришь в телефон, ты забываешь моргать. При чтении книги человек моргает в 2,5 раза чаще, сохраняя зрение здоровым.$$),
  (893, $$Редкое и глубокое дыхание: Чтение выравнивает дыхание, насыщая кровь кислородом и успокаивая тело после беготни.$$),
  (894, $$Быстрое восстановление после спорта: Если почитать книгу после тяжелой тренировки, мышцы восстановятся быстрее, так как организм перейдет в режим отдыха.$$),
  (895, $$Осанка победителя: Читать книгу за столом или держа её на уровне груди гораздо полезнее для спины, чем горбиться над смартфоном.$$),
  (896, $$Минус головная боль: Чтение в тишине снимает мышечное напряжение в шее, помогая избавиться от легкой головной боли без таблеток.$$),
  (897, $$Когнитивный резерв: Каждый час за книгой строит в твоей голове запасные нейронные дорожки. Это твоя страховка, чтобы сохранить острый ум до самой старости.$$),
  (898, $$Гормональный баланс: Чтение снижает уровень адреналина и кортизола, защищая твое сердце и сосуды от лишних перегрузок.$$),
  (899, $$Доход выше на 21%: Ученые выяснили, что дети, в чьих домах было много книг, во взрослом возрасте зарабатывают намного больше своих нечитающих сверстников.$$),
  (900, $$Привычка миллиардеров: Илон Маск, Билл Гейтс и Уоррен Баффет читают по 1–2 книги в неделю. В соцсетях они не сидят — у них просто нет на это времени.$$),
  (901, $$Лидерские качества: Книги учат масштабному мышлению. Ты начнешь видеть тренды и понимать, какие проекты выстрелят, а какие провалятся.$$),
  (902, $$Уверенность на собеседованиях: Начитанного человека видно сразу по тому, как уверенно он держится и как четко отвечает на сложные вопросы.$$),
  (903, $$Легкое освоение профессий: Мозг, привыкший к длинным текстам, легко разберется в коде программирования, чертежах или сложных инструкциях.$$),
  (904, $$Умение доводить дела до конца: Прочесть книгу в 500 страниц — это крутая тренировка упорства. Этот навык поможет тебе запускать свои стартапы и не бросать их на полпути.$$),
  (905, $$Креативность без границ: Чтение расширяет кругозор. Ты сможешь находить гениальные бизнес-решения там, где другие видят тупик.$$),
  (906, $$Уважение в кругу крутых людей: Эрудиция — это пропуск в тусовки умных, успешных и влиятельных людей, где ценят глубину мыслей.$$),
  (907, $$Быстрый карьерный рост: Начитанные сотрудники быстрее становятся руководителями, потому что они умеют координировать команду и круто пишут отчеты.$$),
  (908, $$Лучшая инвестиция в себя: Деньги на гаджеты устареют через пару лет. Знания и навыки, полученные из книг, останутся с тобой на всю жизнь и сделают тебя успешным.$$),
  (909, $$Книга размером с микроба: Самая маленькая книга в мире имеет размер меньше миллиметра. Прочесть её можно только под электронным микроскопом.$$),
  (910, $$Книга-гигант: Самая большая книга по площади имеет размер больше 3 метров в ширину. Чтобы перевернуть страницу, нужны усилия двух человек.$$),
  (911, $$Книга, которая исчезает: Одно португальское издательство напечатало книгу особыми чернилами. Через два месяца после открытия коробки текст полностью исчезает от контакта с воздухом. Это мотивирует не откладывать чтение!$$),
  (912, $$Каникулы — это «собачьи дни»: Слово «каникулы» переводится с латыни как «маленькая собачка». Римляне называли так самые жаркие дни лета, когда на небе всходила звезда Сириус (Каникула), и школы закрывались из-за зноя.$$),
  (913, $$Смерть от смеха: Древний философ Хрисипп умер от хохота, когда напоил своего осла вином и смотрел, как тот пытается есть инжир.$$),
  (914, $$Книги на цепях: В средние века книги стоили так дорого, что в библиотеках их приковывали к полкам железными цепями, чтобы их никто не утащил.$$),
  (915, $$Запах старых книг: Причина приятного ванильного запаха старых книг — химический распад соединений в бумаге. Существует даже термин «библиоосмия» — непреодолимое желание нюхать книги.$$),
  (916, $$Книжные черви реальны: Это не просто обзывательство. Личинки жуков-точильщиков реально прогрызают страницы старых фолиантов, оставляя в них дырочки.$$),
  (917, $$Паровой каток для жесткого диска: Писатель Терри Пратчетт перед смертью приказал раздавить паровым катком жесткий диск своего компьютера, чтобы никто не смог дописать его незавершенные романы. Его волю выполнили!$$),
  (918, $$Стеллаж «БИЛЛИ»: Знаменитый книжный стеллаж из ИКЕА является самой продаваемой мебелью в истории. Каждые 5 секунд в мире покупают один такой стеллаж.$$),
  (919, $$Свобода от алгоритмов: В соцсетях контентом твоего мозга управляет искусственный интеллект, подсовывая видео ради рекламы. Читая книгу, ты сам выбираешь тему и темп мышления.$$),
  (920, $$Тебе никогда не будет скучно: Человек с книгой самодостаточен. Ему не нужно судорожно проверять телефон каждую минуту, чтобы развлечься.$$),
  (921, $$Собственное мнение: Чтение развивает критический взгляд на мир. Тебя будет невозможно увлечь глупой модой или заставить делать то, что делают все.$$),
  (922, $$Проживи тысячу жизней: За одну свою жизнь ты можешь примерить на себя судьбы сотен героев, забрав себе их опыт, победы и выводы.$$),
  (923, $$Внутренний компас: Моральные дилеммы книжных героев помогают тебе четко понять, кто ты сам и какие ценности для тебя по-настоящему важны.$$),
  (924, $$Эстетический вкус: Тот, кто читал великие тексты, начинает ценить качественную музыку, стильную одежду и глубокое кино, отсекая дешевую попсу.$$),
  (925, $$Смелость быть собой: Примеры великих писателей-бунтарей учат не бояться своей непохожести на других и уверенно защищать свои интересы.$$),
  (926, $$Интеллектуальная независимость: Ты сможешь сам выбирать себе авторитетов, а не слепо верить словам блогеров из интернета.$$),
  (927, $$Источник вдохновения на всю жизнь: В любой сложный момент, когда кажется, что всё идет не так, ты сможешь открыть любимую книгу и найти в ней силы двигаться дальше.$$),
  (928, $$Ты создаешь лучшую версию себя: Каждая прочитанная книга оставляет след в твоем характере, делая тебя умнее, сильнее, добрее и круче с каждым днем.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  'LITERATURE',
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;

-- Keep the existing editorial pause for Russia-, Russian-, USSR-, and
-- Soviet-related cards reversible: records remain stored but not delivered.
UPDATE "philology_facts"
SET "isActive" = FALSE, "updatedAt" = CURRENT_TIMESTAMP
WHERE "isActive" = TRUE
  AND "text" ~* '(росси|русск|ссср|советск|большевик|петроград|кремл|сталин|пастернак|достоевск|толст|пушкин|гогол|лермонтов|чехов|есенин|маяковск|тургенев|некрасов|гумилев|ахматов|мандельштам|зощенко|салтыков|жуковск|грибоедов|булгаков|бунин|куприн|горьк|фет|фонвизин|тютчев|жданов|солженицын|стругацк|ильф|петров|набоков|чуковск|крылов|беляев|акунин|гайдар|блок|волошин|бендер|ппш|живаго|облонск|мюнхгаузен)';

